/* REVERT-TYPE1: undoes the two halves of the TYPE-1 ship named as the leading suspect for the
   owner's "runs a lot slower than before" report -- the bundled Geist VARIABLE faces, and the
   14px -> 15px base bump. Injected last in the cascade against the SHIPPED binary, so this is an
   A/B of the real artifact, not a rebuild.

   Geist Sans/Mono are variable (wght 100-900); a variable face is rasterized per weight instance,
   so every distinct weight on screen is its own glyph cache. Segoe UI is static and already
   resident in Windows, which is what the app used before TYPE-1. */
:root {
  --v2-font-sans: "Segoe UI", system-ui, sans-serif;
  --v2-font-mono: Consolas, "Cascadia Mono", ui-monospace, monospace;
  --qpw-font-sans: "Segoe UI", system-ui, sans-serif;
  --qpw-font-mono: Consolas, "Cascadia Mono", ui-monospace, monospace;

  --type-verdict: 37px;
  --type-section: 24px;
  --type-card: 16px;
  --type-body: 14px;
  --type-label: 12px;
  --type-data: 12px;
}
